#!/usr/bin/env python3
"""MFRE (Fase 16): complete the Spanish catalog (launcher/lang/es.json).

The fork's UI spoke a mix of English and Spanish: 460 strings the launcher
asks for (`tr()`) had no entry in es.json. This script adds them, in themed
batches (Play, mods and builds, instances, servers, settings, errors), and
validates every value the way `i18n::tests` does: the {holes} of a value match
its key's, and no value is empty. The catalog stays sparse on purpose
(philosophy of patch 0006): what is not translated here shows its English
source, never dummy English written into the table.

    python3 tools/mfre_lang_es.py --report   # counts only, nothing written
    python3 tools/mfre_lang_es.py --apply    # write es.json

Terminology follows the existing catalog: compilar/compilación (build),
Ajustes, Almacenamiento, Inicio (Home), Acerca de, Carpeta de datos, equipo,
instancia, pack, mod, launcher/MineForge Launcher.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ES = ROOT / "launcher" / "lang" / "es.json"

