def holes(s: str) -> list[str]:
    return sorted(re.findall(r"\{(\w+)\}", s))


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--report", action="store_true")
    args = ap.parse_args()
    table = json.loads(ES.read_text(encoding="utf-8"))
    missing = [k for k in SPANISH if k not in table]
    dupes = [k for k in SPANISH if k in table]
    for en, es in SPANISH.items():
        assert holes(en) == holes(es), f"holes differ: {en!r}"
        assert es.strip(), f"empty value: {en!r}"
    print(f"es.json: {len(table)} keys; SPANISH holds {len(SPANISH)}; "
          f"absent from the catalog: {len(missing)}; already present: {len(dupes)}")
    if missing:
        for k in missing[:10]:
            print("  absent:", repr(k))
    if args.report or not args.apply:
        return 0
    table.update(SPANISH)
    ES.write_text(json.dumps(table, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {ES} with {len(table)} keys")
    return 0


if __name__ == "__main__":
    sys.exit(main())
